	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void terminalWaitsForBothOwnersRegardlessOfSettlementOrder(boolean contextFirst) {
		Capture capture = NativeExecutionObservation.begin(3, 8);
		RowRegion row = capture.reserveRow(7);
		assertThat(row).isNotNull();
		row.opened();
		row.started();
		row.producerFinished(true, false, false);
		var before = capture.snapshot();
		assertThat(before.events()).extracting(Event::phase).containsExactly(Phase.OPENED, Phase.STARTED);
		if (contextFirst) {
			row.contextFinished(false);
		} else {
			row.carrierFinished(false);
		}
		assertThat(capture.snapshot().events()).isEqualTo(before.events());
		if (contextFirst) {
			row.carrierFinished(false);
		} else {
			row.contextFinished(false);
		}
		row.contextFinished(false);
		row.carrierFinished(false);
		assertThat(capture.snapshot().events()).extracting(Event::phase)
				.containsExactly(Phase.OPENED, Phase.STARTED, Phase.COMPLETED);
		assertThat(before.events()).extracting(Event::phase).containsExactly(Phase.OPENED, Phase.STARTED);
	}

